import{_ as i,o as a,c as s,a2 as t}from"./chunks/framework.e4u2V5E7.js";const u=JSON.parse('{"title":"Code review process, quality checklist, feedback guidelines, and approval criteria","description":"Code review process, quality checklist, feedback guidelines, and approval criteria","frontmatter":{"title":"Code review process, quality checklist, feedback guidelines, and approval criteria","description":"Code review process, quality checklist, feedback guidelines, and approval criteria"},"headers":[],"relativePath":"skills/code-review-standards.md","filePath":"skills/code-review-standards.md","lastUpdated":1784485118000}'),l={name:"skills/code-review-standards.md"};function r(n,e,o,d,c,h){return a(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="code-review-process-quality-checklist-feedback-guidelines-and-approval-criteria" tabindex="-1">Code review process, quality checklist, feedback guidelines, and approval criteria <a class="header-anchor" href="#code-review-process-quality-checklist-feedback-guidelines-and-approval-criteria" aria-label="Permalink to &quot;Code review process, quality checklist, feedback guidelines, and approval criteria&quot;">​</a></h1><div class="tip custom-block" style="padding:1rem;"><strong>Skill:</strong> <code>code-review-standards</code> | <strong>Category:</strong> quality | <strong>Priority:</strong> high | <strong>Level:</strong> concept </div><h1 id="code-review-standards" tabindex="-1">Code Review Standards <a class="header-anchor" href="#code-review-standards" aria-label="Permalink to &quot;Code Review Standards&quot;">​</a></h1><h2 id="purpose" tabindex="-1">Purpose <a class="header-anchor" href="#purpose" aria-label="Permalink to &quot;Purpose&quot;">​</a></h2><p>Guide code review process with quality checklists and feedback guidelines.</p><h2 id="when-to-use" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use" aria-label="Permalink to &quot;When to Use&quot;">​</a></h2><ul><li>Reviewing pull requests</li><li>Setting up review processes</li><li>Training new reviewers</li><li>Establishing quality gates</li></ul><h2 id="core-concepts" tabindex="-1">Core Concepts <a class="header-anchor" href="#core-concepts" aria-label="Permalink to &quot;Core Concepts&quot;">​</a></h2><h3 id="review-checklist" tabindex="-1">Review Checklist <a class="header-anchor" href="#review-checklist" aria-label="Permalink to &quot;Review Checklist&quot;">​</a></h3><p><strong>Correctness</strong></p><ul><li>Does the code solve the intended problem?</li><li>Are edge cases handled?</li><li>Are error paths handled?</li></ul><p><strong>Security</strong></p><ul><li>Are inputs validated?</li><li>Are secrets handled properly?</li><li>Is authentication/authorization checked?</li></ul><p><strong>Quality</strong></p><ul><li>Is the code readable and maintainable?</li><li>Are there code smells (duplication, long functions)?</li><li>Are types explicit (no <code>any</code>)?</li></ul><p><strong>Testing</strong></p><ul><li>Are critical paths tested?</li><li>Are tests meaningful (not just coverage)?</li><li>Do tests cover error cases?</li></ul><h3 id="feedback-guidelines" tabindex="-1">Feedback Guidelines <a class="header-anchor" href="#feedback-guidelines" aria-label="Permalink to &quot;Feedback Guidelines&quot;">​</a></h3><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Good: Specific, actionable</span></span>
<span class="line"><span>&quot;Consider using a Set here for O(1) lookups instead of Array.includes at line 45&quot;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Bad: Vague, non-actionable</span></span>
<span class="line"><span>&quot;This could be better&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h3 id="review-priorities" tabindex="-1">Review Priorities <a class="header-anchor" href="#review-priorities" aria-label="Permalink to &quot;Review Priorities&quot;">​</a></h3><ol><li><strong>Critical</strong>: Security, data loss, corruption</li><li><strong>Major</strong>: Bugs, performance issues</li><li><strong>Minor</strong>: Style, naming, minor improvements</li><li><strong>Nit</strong>: Typos, formatting</li></ol><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li>Review within 24 hours</li><li>Focus on critical and major issues</li><li>Provide context and examples</li><li>Approve with minor suggestions</li><li>Block only for critical issues</li><li>Document review decisions</li></ul><h2 id="anti-patterns" tabindex="-1">Anti-Patterns <a class="header-anchor" href="#anti-patterns" aria-label="Permalink to &quot;Anti-Patterns&quot;">​</a></h2><ul><li>Rubber-stamping approvals</li><li>Blocking for style preferences</li><li>Not reviewing test quality</li><li>Ignoring security implications</li><li>Reviewing too much at once</li></ul><h2 id="when-to-use-1" tabindex="-1">When to Use <a class="header-anchor" href="#when-to-use-1" aria-label="Permalink to &quot;When to Use&quot;">​</a></h2><ul><li>File patterns match the skill&#39;s activation rules</li><li>Keywords in the conversation match the skill&#39;s domain</li><li>A related agent delegates to this skill</li></ul><h2 id="when-not-to-use" tabindex="-1">When NOT to Use <a class="header-anchor" href="#when-not-to-use" aria-label="Permalink to &quot;When NOT to Use&quot;">​</a></h2><ul><li>When the task falls outside this skill&#39;s domain</li><li>When a more specific skill exists for the task</li><li>When the skill&#39;s dependencies are not met</li></ul><h2 id="related-agents" tabindex="-1">Related Agents <a class="header-anchor" href="#related-agents" aria-label="Permalink to &quot;Related Agents&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/agents/">Agents Registry</a> for agents that use this skill.</p><h2 id="related-skills" tabindex="-1">Related Skills <a class="header-anchor" href="#related-skills" aria-label="Permalink to &quot;Related Skills&quot;">​</a></h2><p>See <a href="/Ahmed-Enterprise-AI-Workspace/skills/">Skills Registry</a> for related skills in the same cluster.</p><h2 id="customization-guide" tabindex="-1">Customization Guide <a class="header-anchor" href="#customization-guide" aria-label="Permalink to &quot;Customization Guide&quot;">​</a></h2><ol><li>Copy the skill to <code>.opencode/skills/</code> in your project</li><li>Modify the activation rules to match your project patterns</li><li>Add project-specific examples and templates</li><li>Update the related agents and skills references</li></ol><h2 id="extension-guide" tabindex="-1">Extension Guide <a class="header-anchor" href="#extension-guide" aria-label="Permalink to &quot;Extension Guide&quot;">​</a></h2><ol><li>Add new sections to the SKILL.md file</li><li>Include code examples for new patterns</li><li>Update anti-patterns with new findings</li><li>Maintain cross-references to related skills</li><li>Keep the skill focused on its core purpose</li></ol>`,37)])])}const g=i(l,[["render",r]]);export{u as __pageData,g as default};
